sqlGroup.select:
select a.id, a.`name`, a.address, a.phone, a.scale, a.is_new, date_format(a.created_time,'%Y-%m-%d %H:%i:%s') as created_time, cs.`name` AS createdStaffName, a.verify_status
from jml_account a left join jml_staff cs ON a.created_staff_id = cs.id
and a.name like '%${multiFiled}%'
and a.province = #{province}
and a.city = #{city}
order by a.created_time desc
